{"path": "sgf_parsing.py", "content": "class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other

    def __repr__(self):
        return f"SgfTree({self.properties!r}, {self.children!r})"


class _Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else None

    def parse_tree(self):
        """Parse '(' node+ tree* ')' starting at current position."""
        if self.peek() != "(":
            raise ValueError("tree missing")
        self.pos += 1
        if self.peek() != ";":
            if self.peek() == ")":
                raise ValueError("tree with no nodes")
            raise ValueError("tree missing")
        nodes = []
        while self.peek() == ";":
            self.pos += 1
            nodes.append(SgfTree(self.parse_properties()))
        variations = []
        while self.peek() == "(":
            variations.append(self.parse_tree())
        if self.peek() != ")":
            raise ValueError("tree missing")
        self.pos += 1
        # Chain sequential nodes; variations attach to the last node.
        nodes[-1].children = variations
        for parent, child in zip(nodes, nodes[1:]):
            parent.children = [child]
        return nodes[0]

    def parse_properties(self):
        properties = {}
        while self.peek() is not None and self.peek() not in ";()":
            start = self.pos
            while self.peek() is not None and self.peek().isalpha():
                self.pos += 1
            key = self.text[start:self.pos]
            if not key:
                raise ValueError("properties without delimiter")
            if not key.isupper():
                raise ValueError("property must be in uppercase")
            if self.peek() != "[":
                raise ValueError("properties without delimiter")
            values = []
            while self.peek() == "[":
                self.pos += 1
                values.append(self.parse_value())
            if key in properties:
                raise ValueError(f"duplicate property {key}")
            properties[key] = values
        return properties

    def parse_value(self):
        out = []
        while True:
            char = self.peek()
            if char is None:
                raise ValueError("properties without delimiter")
            self.pos += 1
            if char == "]":
                return "".join(out)
            if char == "\\":
                char = self.peek()
                if char is None:
                    raise ValueError("properties without delimiter")
                self.pos += 1
                if char == "\n":
                    continue  # escaped newline is removed
            if char != "\n" and char.isspace():
                char = " "
            out.append(char)


def parse(input_string):
    parser = _Parser(input_string)
    tree = parser.parse_tree()
    if parser.pos != len(input_string):
        raise ValueError("tree missing")
    return tree
